"""Default module configs for opticnode gRPC modules."""

from __future__ import annotations

from typing import Any

from optichub.grpc_client import ModuleInfo

KNOWN_NODE_MODULES: tuple[str, ...] = (
    "command_runner",
    "prefect_worker",
    "lsm_process_server",
    "oct_process_server",
    "redis_queue_worker",
    "redis_queue_burst_worker",
    "lsm_watcher",
    "oct_watcher",
    "primocache_monitor",
)


def default_module_config(module: str) -> dict[str, Any]:
    if module == "command_runner":
        return {
            "max_results": 100,
            "default_timeout_s": 30.0,
            "max_timeout_s": 600.0,
            "max_output_chars": 200_000,
        }
    if module == "prefect_worker":
        return {"work_pool": "default", "worker_count": 1, "extra_args": []}
    if module == "lsm_process_server":
        return {"concurrent_workers": 2, "extra_args": []}
    if module == "oct_process_server":
        return {
            "project_name": "",
            "deployment_name": "local",
            "concurrency_limit": 1,
            "exclude": [],
            "extra_args": [],
        }
    if module == "redis_queue_worker":
        return {"queue_name": "", "num_workers": 1}
    if module == "redis_queue_burst_worker":
        return {"queue_name": "", "num_workers": 1}
    if module == "lsm_watcher":
        return {
            "watch_path": "",
            "redis_queue_name": "",
            "poll_interval": 5,
            "stability_seconds": 15,
            "force_resend": False,
            "project_name": "",
            "slice_offset": 0,
        }
    if module == "oct_watcher":
        return {
            "watch_path": "",
            "redis_queue_name": "",
            "poll_interval": 5,
            "stability_seconds": 15,
            "force_resend": False,
            "project_name": "",
            "slice_offset": 0,
            "mosaic_ranges": "1:999999",
            "project_base_path": "",
            "min_complex_file_size_bytes": 1,
            "prefer_spectral_for_complex_with_spectral": True,
        }
    if module == "primocache_monitor":
        return {"poll_interval_s": 15.0}
    return {}


def merged_config(module: str, info: ModuleInfo | None) -> dict[str, Any]:
    base = default_module_config(module)
    if info and info.config:
        merged = {**base, **info.config}
        if module == "prefect_worker" and "extra_args" in info.config:
            merged["extra_args"] = list(info.config.get("extra_args") or [])
        return merged
    return base
